/** The result of methods that return nothing: `{}`. */
export type Empty = { [key: string]: unknown };

export type ErrorInfo = {
  kind: string;
  message: string;
  retryable: boolean;
  status?: number | null;
};

export type ErrorKind = "auth" | "quota_exceeded" | "rate_limited" | "overloaded" | "server" | "network" | "timeout" | "context_overflow" | "invalid_request" | "content_filtered" | "protocol" | "unknown";

export type Event = {
  /** Strictly increasing within a session, starting at 1. */
  seq: number;
  ts: number;
} & ({
  context?: ContextUsage | null;
  context_window: number;
  cwd: string;
  model: string;
  permission_mode: PermissionMode;
  protocol_version: number;
  resumed: boolean;
  session_file: string;
  session_id: string;
  thinking: ThinkingLevel;
  type: "session_started";
  /** Totals recorded in the log so far; zero for a new session. */
  usage: UsageTotals;
} | {
  task_id: string;
  /** What started the task. */
  trigger?: TaskTrigger;
  type: "task_started";
} | {
  /** The context size checked before this turn's request. */
  context?: ContextUsage | null;
  task_id: string;
  turn: number;
  type: "turn_started";
} | {
  message_id: string;
  role: Role;
  type: "message_started";
} | {
  delta: Delta;
  message_id: string;
  type: "message_delta";
} | {
  /** Set when the message is a sub-agent's report delivered to this session. */
  mail?: MailInfo | null;
  message: Message;
  message_id: string;
  /** The skills the user's message mentions with `/skill:name`, in order: show those mentions as tags. */
  skills?: SkillUse[];
  type: "message_completed";
} | {
  attempt: number;
  delay_ms: number;
  error: ErrorInfo;
  type: "stream_retry";
} | {
  info: DocInfo;
  type: "doc_opened";
} | {
  args: unknown;
  call_id: string;
  category: ToolCategory;
  locations?: Location[];
  name: string;
  /** One-line description for display, e.g. the command or `read <path>`. */
  title: string;
  type: "tool_started";
} | {
  call_id: string;
  type: "tool_running";
} | {
  call_id: string;
  text: string;
  type: "tool_progress";
} | {
  call_id: string;
  /** Shared with the history; the JSON is the plain message. */
  result: ToolResultMessage;
  type: "tool_completed";
} | {
  args: unknown;
  call_id: string;
  name: string;
  /** The call works in the user's own browser, with their real sign-ins, rather than the built-in one (connectors-entry-design §3.4): clients say so. */
  own_browser?: boolean;
  /** Site permissions that `approve_for_session` may keep; its `grant` picks one, the first by default. */
  proposed_grants?: SiteGrant[];
  /** Mode that `approve_for_session` switches the session to. With none of this, `proposed_rule` and `proposed_grants`, approving for the session approves this call only. */
  proposed_mode?: PermissionMode | null;
  /** Command prefix that `approve_for_session` allows from then on. */
  proposed_rule?: CommandRule | null;
  reason?: string | null;
  summary: string;
  type: "approval_requested";
} | {
  call_id: string;
  decision: ApprovalDecision;
  type: "approval_resolved";
} | {
  reason: CompactionReason;
  type: "compaction_started";
} | {
  /** The session's compaction count, from 1. Distinct from the event sequence. */
  compaction_seq: number;
  context: ContextUsage;
  /** Skills in use whose instructions were kept, most recently used first. */
  kept_skills?: string[];
  reason: CompactionReason;
  /** User messages kept word for word. */
  retained_messages: number;
  summary: string;
  tokens_after: number;
  tokens_before: number;
  type: "compaction_completed";
} | {
  error: ErrorInfo;
  reason: CompactionReason;
  type: "compaction_failed";
} | {
  task_id: string;
  turn: number;
  type: "turn_completed";
  usage: Usage;
} | {
  last_message?: string | null;
  reason: CompletionReason;
  task_id: string;
  type: "task_completed";
  usage: UsageTotals;
} | {
  error: ErrorInfo;
  /** What still waited, handed back as with an interruption. */
  returned_input?: UserMessage[];
  task_id: string;
  type: "task_failed";
  usage: UsageTotals;
} | {
  returned_input: UserMessage[];
  task_id: string;
  type: "task_interrupted";
  usage: UsageTotals;
} | {
  queued: QueuedInput[];
  type: "queue_changed";
} | {
  id: string;
  type: "input_withdrawn";
} | {
  message_id: string;
  /** The sub-agents started in the part taken back: they are gone. */
  removed_agents?: string[];
  /** What still waited for the running task, handed back as with an interruption. */
  returned_input?: UserMessage[];
  type: "session_rewound";
} | {
  context_window: number;
  model: string;
  permission_mode: PermissionMode;
  thinking: ThinkingLevel;
  type: "settings_changed";
} | {
  title: string;
  type: "title_changed";
} | {
  archived: boolean;
  type: "archived_changed";
} | {
  call_id: string;
  name: string;
  reason?: string | null;
  summary: string;
  type: "approval_refused";
} | {
  /** What the warning is about, for a client that words or places it itself. Absent for one-off warnings, which are only shown as `message`. */
  code?: WarningCode | null;
  message: string;
  type: "warning";
} | {
  /** Time since the connection attempt began. */
  elapsed_ms?: number | null;
  error?: string | null;
  server: string;
  state: McpServerState;
  /** Tools offered after filtering, when ready. */
  tools: number;
  type: "mcp_server_status";
} | {
  agent_id: string;
  /** The `spawn_agent` call that started it. */
  call_id: string;
  /** What the user sees for it: a few words on what it works on. */
  description?: string;
  /** Its handle: how the main agent addresses it. */
  name: string;
  session_file: string;
  type: "agent_started";
} | {
  agent_id: string;
  /** How long its last round of work took (an idle status). */
  elapsed_ms?: number | null;
  error?: ErrorInfo | null;
  name: string;
  status: AgentStatus;
  /** The start of its report. */
  summary?: string | null;
  type: "agent_status";
  /** What its last round of work cost. */
  usage?: UsageTotals | null;
} | {
  agent_id: string;
  event: Event;
  type: "agent_event";
} | {
  report: ContextReport;
  type: "context_reported";
} | {
  type: "idle";
} | {
  type: "session_closed";
});

/** Event classes a connection can opt out of when attaching. */
