export type SkillsFilesResult = {
  /** At most 500 entries, 6 levels deep. */
  files: SkillFileInfo[];
  skill_md: string;
  /** `skill_md` was cut at 256 KB. */
  truncated: boolean;
};

export type SkillsInstallParams = {
  /** Required for the project scope: a directory in the project. */
  cwd?: string | null;
  /** Read and check only; write nothing. */
  dry_run?: boolean;
  /** A skill directory, a `SKILL.md`, or a `.zip` or `.skill` archive. */
  from: string;
  /** Replace a skill of the same name (moved to the trash first). */
  replace?: boolean;
  scope?: SkillInstallScope;
  /** Recorded in `.finx-source.json`; absent: an upload. */
  source?: SkillSource | null;
};

export type SkillsInstallResult = {
  /** A dry run found a skill of the same name there. */
  conflict?: string | null;
  /** As installed; for a dry run, as it would be. */
  skill: SkillEntry;
  target: string;
};

/** Parameters of `skills/list`: `session_id` or `cwd`, or neither for what a session without a project would find. */
export type SkillsListParams = {
  /** An absolute directory: every skill a session started there would find now, those it would not use included, and its catalog. The same as `finx skills --all --json`. */
  cwd?: string | null;
  /** A loaded session: the skills it started with, described from their files now, and what typing `/` offers there. */
  session_id?: string | null;
};

export type SkillsListResult = {
  /** For a directory. */
  catalog?: CatalogInfo | null;
  /** What typing `/` offers there: the built-in commands first, then the skills as `skill:name`. */
  commands?: CommandInfo[];
  /** `skills.enabled` */
  enabled: boolean;
  /** Other apps' folders that hold skills but are not read (`skills.other_apps` is off). */
  not_read?: string[];
  /** In priority order. */
  skills: SkillEntry[];
  warnings: string[];
};

export type SkillsReadParams = {
  /** A file in it, as `skills/files` lists it. */
  file: string;
  /** The skill's directory or its `SKILL.md`. */
  path: string;
};

export type SkillsReadResult = {
  /** Not UTF-8 text (an image, an archive, a program). */
  binary: boolean;
  /** The file is a PNG, JPEG, GIF or WebP image, by its signature: its bytes, to show. */
  image?: SkillImage | null;
  /** Empty when the file is not text. */
  text: string;
  /** `text` was cut at 256 KB. */
  truncated: boolean;
};

export type SkillsRemoveParams = {
  path: string;
};

export type SkillsSetEnabledParams = {
  enabled: boolean;
  /** The skill's `SKILL.md` or directory. */
  path: string;
};

export type SkillsSetEnabledResult = {
  /** The user's configuration file that now lists or no longer lists it. */
  file: string;
  /** A name-form entry for the same skill was removed too. */
  removed_names?: string[];
};

/** Result of `session/resume` and `session/attach`. */
export type SnapshotResult = {
  snapshot: SessionSnapshot;
};

export type Speaker = "user" | "bot";

export type StopReason = "stop" | "length" | "tool_use" | "error" | "aborted";

export type TaskOutcome = "completed" | "failed" | "interrupted";

/** What started a task. */
export type TaskTrigger = "user" | "mail";

/** How hard a model thinks. `Default` sends nothing and leaves it to the provider; the others are the providers' own levels, and a model offers only those it supports (docs/kernel/model-catalog-design.md §18). */
export type ThinkingLevel = "default" | "off" | "minimal" | "low" | "medium" | "high" | "xhigh" | "max" | "on";

/** Connection details for a subscription product, never its secret or entitlement status. */
export type TokenPlanSummary = {
  api: string;
  base_url: string;
  dynamic_models: boolean;
  key_url: string;
};

/** What a tool call does, for display. The values are a subset of the ACP tool kinds. */
export type ToolCategory = "read" | "edit" | "delete" | "move" | "search" | "execute" | "fetch" | "other";

/** One tool, as `tools/list` and `finx tools --json` give it. */
export type ToolEntry = {
  available: boolean;
  description: string;
  /** `base`, `agents`, `deferred` (the two tools that reach the others), `web`, `doc`, `browser`, `cua`, `bot` or `mcp`. */
  group: string;
  kind: ToolEntryKind;
  /** In the model's tool list from the start, rather than found through `tool_search`. */
  loaded: boolean;
  name: string;
  /** What it takes: the setting or the component missing, or a limit on an available tool. */
  needs?: string | null;
  origin: ToolEntryOrigin;
  /** JSON Schema of its arguments. */
  parameters: unknown;
};

/** What a tool does to the world: read-only tools may run side by side. */
export type ToolEntryKind = "read_only" | "mutating";

/** Where a tool comes from. */
export type ToolEntryOrigin = "builtin" | "mcp";

export type ToolResultMessage = {
  call_id: string;
  /** Sent to the model. */
  content: UserContent[];
  /** For user interfaces and logs; never sent to the model. */
  details?: unknown;
  duration_ms?: number | null;
  is_error: boolean;
  tool_name: string;
  ts: number;
};

export type ToolState = {
  args: unknown;
  call_id: string;
  category: ToolCategory;
  name: string;
  /** The most recent progress output, capped. */
  progress_tail?: string;
  running: boolean;
  title: string;
};

/** Parameters of `tools/list`. */
export type ToolsListParams = {
  /** A loaded session: the tools it really has now, those of connected MCP servers included. Without one, the built-in tools under the current configuration. */
  session_id?: string | null;
};

export type ToolsListResult = {
  tools: ToolEntry[];
};

export type TraceDirection = "up" | "down";

export type TranscriptItem = {
  mail?: MailInfo | null;
  message: Message;
  message_id: string;
  skills?: SkillUse[];
  type: "message";
} | {
  call_id: string;
  result: ToolResultMessage;
  type: "tool_result";
} | {
  error?: ErrorInfo | null;
  outcome: TaskOutcome;
  reason?: CompletionReason | null;
  task_id: string;
  ts: number;
  type: "task_end";
  usage?: UsageTotals | null;
};

export type TranscriptPage = {
  /** Cursor for earlier items (opaque); absent at the start of the session. */
  before?: string | null;
  /** Oldest first. */
  items: TranscriptItem[];
};

export type Usage = {
  cache_read: number;
  cache_write: number;
  cost: Cost;
  /** Input tokens that did not hit the cache. */
  input: number;
  /** Output tokens, reasoning included. */
  output: number;
  /** The reasoning part of `output`, when the provider reports it. */
  reasoning?: number | null;
};

/** Usage summed per model (`provider/model`). */
export type UsageTotals = {
  per_model: { [key: string]: Usage };
};

export type UserContent = {
  text: string;
  type: "text";
} | {
  data: string;
  mime_type: string;
  type: "image";
};

export type UserMessage = {
  content: UserContent[];
  ts: number;
};

/** Warnings a client may recognise. A client meeting a code it does not know shows `message`. */
export type WarningCode = "bypass_permissions" | "mcp_servers_not_ready" | "resend_rejected";

/** Why a search with a service failed. */
export type WebSearchErrorKind = "auth_failed" | "quota_exhausted" | "rate_limited" | "unreachable" | "bad_response";

export type WebSearchFailure = {
  /** When, in milliseconds since the epoch. */
  at_ms: number;
  kind: WebSearchErrorKind;
};

/** Where a service's key comes from. */
export type WebSearchKeySource = "saved" | "env" | "account";

/** What a service needs before it can be used. */
export type WebSearchNeeds = "key" | "nothing" | "account";

export type WebSearchSetKeyParams = {
  key: string;
  source: string;
};

/** The result of `web_search/set_key`. A key the service refused is not saved; one that could not be tried is, and the service then goes first in the list, switched on. */
export type WebSearchSetKeyResult = {
  saved: boolean;
  test: WebSearchTestResult;
};

/** One service, in the list's order. */
export type WebSearchSource = {
  /** It has what it needs. */
  configured: boolean;
  /** Its switch: searches skip it when off. */
  enabled: boolean;
  /** Its last search, when that failed; a search that works clears it. */
  failure?: WebSearchFailure | null;
  id: string;
  key?: WebSearchKeySource | null;
  /** The variable the key comes from. */
  key_env?: string | null;
  /** Where to get a key. */
  key_url?: string | null;
  name: string;
  needs: WebSearchNeeds;
};

/** The result of `web_search/status`. */
export type WebSearchStatus = {
  /** The service searches use now: the first that is usable and whose last search did not fail. */
  current?: string | null;
  /** `web_search.enabled`. */
  enabled: boolean;
  sources: WebSearchSource[];
};

export type WebSearchTestParams = {
  source: string;
};

/** How one real search went. */
export type WebSearchTestResult = {
  count: number;
  elapsed_ms: number;
  error?: WebSearchErrorKind | null;
  ok: boolean;
};

/** A session's tab in the user's own browser, as the extension reports it: the extension keeps which tab is whose, across reconnects and restarts of the service (browser-design §8.4.7). */
export type YoursTab = {
  /** The agent is attached to it now, so a task is using it; Chrome shows its debugging bar. */
  attached?: boolean;
  target_id: string;
  title: string;
  url: string;
};

